// VERBATIM COPY of pi/packages/protocol/src/protocol.ts isServerId (the TypeBox
// pattern compiled to an equivalent regex; typebox is not installed here).
export function isServerId(value) {
	return typeof value === "string" && /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(value);
}
